    """Tuned Best Fit (lo=1, hi=31, penalty=83): the tightest bin wins, but leaving a gap
    strictly between 1 and 31 units costs 83. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 83 * ((r > 1) & (r < 31))

