    """Tuned Best Fit (lo=10, hi=15, penalty=80): the tightest bin wins, but leaving a gap
    strictly between 10 and 15 units costs 80. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 80 * ((r > 10) & (r < 15))

